mod solution;

fn main() {
    let cases = [
    (r#"grid=ABCE,SFCS,ADEE word=ABCCED"#, r#"true"#),
    (r#"grid=A word=B"#, r#"false"#),
    (r#"
grid=A word=B
"#, r#"false"#),
    (r#"  
grid=ABCE,SFCS,ADEE word=ABCCED
  "#, r#"true"#),
    ];
    for (case_index, (input, expected)) in cases.iter().enumerate() {
        if solution::solve(input) != *expected {
            eprintln!("PRIVATE CASE {} FAILED", case_index + 1);
            std::process::exit(1);
        }
    }
    println!("PASS word-grid-search");
}
